import 'dart:convert';
import 'dart:typed_data';

import 'package:flutter_crypto_security/flutter_crypto_security.dart';
import 'package:flutter_test/flutter_test.dart';

/// Fixed 2048-bit test key pair (base64 PEM, generated by the Go library).
const serverPrivateKey =
    "";
const serverPublicKey =
    "";

/// A private key and envelope captured from the production Go backend. They pin
/// the wire format: raw 32-byte AES key inside PKCS#1 v1.5, uppercase fields.
const legacyServerPrivateKey =
    "";
const legacyServerResponse = {
  'Payload':
      '',
  'Key':
      '',
  'Nonce': 'yok6ogjvWG24NeMD',
};

const samplePlaintext = '{"Code":"172","Amount":100.0,"Currency":"INR"}';

Uint8List utf8Bytes(String s) => Uint8List.fromList(utf8.encode(s));

void main() {
  group('Key handling', () {
    test('parses base64 PKCS#1 private and PKIX public keys', () {
      final priv = Crypto.fromBase64PrivateKey(serverPrivateKey);
      final pub = Crypto.fromBase64PublicKey(serverPublicKey);
      expect(priv.privateKey, isNotNull);
      expect(pub.publicKey, isNotNull);
      expect(priv.privateKey!.modulus, equals(pub.publicKey!.modulus));
      expect(pub.publicKey!.modulus!.bitLength, equals(2048));
    });

    test('rejects invalid keys', () {
      expect(() => Crypto.fromBase64PrivateKey('not base64!'),
          throwsArgumentError);
      expect(() => Crypto.fromBase64PrivateKey(base64Encode(utf8.encode('x'))),
          throwsArgumentError);
      expect(() => Crypto.fromBase64PrivateKey(serverPublicKey),
          throwsArgumentError);
      expect(() => Crypto.fromBase64PublicKey(serverPrivateKey),
          throwsArgumentError);
    });

    test('generateRSAKeyPair produces keys in the shared PEM format', () {
      final (priv, pub) = Crypto.generateRSAKeyPair();
      expect(utf8.decode(base64Decode(priv)),
          startsWith('-----BEGIN RSA PRIVATE KEY-----'));
      expect(utf8.decode(base64Decode(pub)),
          startsWith('-----BEGIN PUBLIC KEY-----'));

      final message = utf8Bytes('generated key round trip');
      final encrypted = Crypto.fromBase64PublicKey(pub)
          .encryptWithUint8ListPublicKey(message);
      final decrypted = Crypto.fromBase64PrivateKey(priv)
          .decryptWithPrivateKey(base64Encode(encrypted));
      expect(decrypted, equals(message));
    });

    test('PEM codec round-trips and re-encodes byte-identical DER', () {
      final priv = RsaKeyCodec.parsePrivateKeyBase64(serverPrivateKey);
      final pub = RsaKeyCodec.parsePublicKeyBase64(serverPublicKey);
      expect(
          RsaKeyCodec.encodePrivateKeyBase64(priv), equals(serverPrivateKey));
      expect(RsaKeyCodec.encodePublicKeyBase64(pub), equals(serverPublicKey));
    });
  });

  group('RSA', () {
    test('PKCS#1 v1.5 encrypt with public key, decrypt with private key', () {
      final symmetricKey = Crypto.generateRandomBytes(32);
      final plaintext = base64Encode(symmetricKey);

      final encryptedMessage = Crypto.fromBase64PublicKey(serverPublicKey)
          .encryptWithPublicKey(plaintext);
      expect(encryptedMessage.length, equals(256));

      final decrypted = Crypto.fromBase64PrivateKey(serverPrivateKey)
          .decryptWithPrivateKey(base64Encode(encryptedMessage));
      expect(utf8.decode(decrypted), equals(plaintext));
    });

    test('PKCS#1 v1.5 raw bytes round trip (32-byte AES key)', () {
      final aesKey = Crypto.generateRandomBytes(32);
      final encrypted = Crypto.fromBase64PublicKey(serverPublicKey)
          .encryptWithUint8ListPublicKey(aesKey);
      final decrypted = Crypto.fromBase64PrivateKey(serverPrivateKey)
          .decryptWithPrivateKey(base64Encode(encrypted));
      expect(decrypted, equals(aesKey));
    });

    test('OAEP-SHA256 round trip and is distinct from PKCS#1 v1.5', () {
      final message = utf8Bytes('OAEP message');
      final encrypted = Crypto.fromBase64PublicKey(serverPublicKey)
          .encryptWithPublicKeyOAEP(message);
      final priv = Crypto.fromBase64PrivateKey(serverPrivateKey);
      expect(priv.decryptWithPrivateKeyOAEP(base64Encode(encrypted)),
          equals(message));
      expect(() => priv.decryptWithPrivateKey(base64Encode(encrypted)),
          throwsA(anything));
    });

    test('rejects oversized messages and wrong keys', () {
      final pub = Crypto.fromBase64PublicKey(serverPublicKey);
      expect(() => pub.encryptWithUint8ListPublicKey(Uint8List(246)),
          throwsArgumentError);
      final (otherPriv, _) = Crypto.generateRSAKeyPair();
      final encrypted = pub.encryptWithUint8ListPublicKey(Uint8List(32));
      expect(
          () => Crypto.fromBase64PrivateKey(otherPriv)
              .decryptWithPrivateKey(base64Encode(encrypted)),
          throwsA(anything));
      expect(() => pub.decryptWithPrivateKey('AAAA'), throwsArgumentError);
    });
  });

  group('AES-GCM', () {
    test('encrypt and decrypt', () {
      final key = Crypto.generateRandomBytes(32);
      final nonce = Crypto.generateNonce();
      expect(nonce.length, equals(12));

      final (ciphertext, nonceB64) =
          Crypto.encryptWithAES(key, nonce, utf8Bytes(samplePlaintext));
      expect(base64Decode(ciphertext).length,
          equals(utf8.encode(samplePlaintext).length + 16));
      expect(Crypto.decryptWithAES(key, ciphertext, nonceB64),
          equals(samplePlaintext));
      expect(Crypto.decryptWithAESGCM(key, ciphertext, nonceB64),
          equals(samplePlaintext));
    });

    test('decrypts vector produced by the Go library', () {
      final key = base64Decode('NwUqUByc21I71POTifDQ1OPjhwBIFNd1Q2wodYbxOkE=');
      final plaintext = Crypto.decryptWithAES(
          key, 'AHlo1s9rKPRSL3qTv9LqN+giCtQ9', '/jy/osqLyF8pgnI8');
      expect(plaintext, isNotEmpty);
    });

    test('fails with wrong key or tampered ciphertext', () {
      final key = Crypto.generateRandomBytes(32);
      final wrongKey = Crypto.generateRandomBytes(32);
      final nonce = Crypto.generateNonce();
      final (ciphertext, nonceB64) =
          Crypto.encryptWithAES(key, nonce, utf8Bytes(samplePlaintext));

      expect(() => Crypto.decryptWithAES(wrongKey, ciphertext, nonceB64),
          throwsA(anything));

      final tampered = base64Decode(ciphertext);
      tampered[0] ^= 0xff;
      expect(() => Crypto.decryptWithAES(key, base64Encode(tampered), nonceB64),
          throwsA(anything));
    });

    test('rejects bad key or nonce sizes', () {
      expect(
          () => Crypto.encryptWithAES(
              Uint8List(16), Crypto.generateNonce(), Uint8List(1)),
          throwsArgumentError);
      expect(
          () => Crypto.encryptWithAES(
              Crypto.generateRandomBytes(32), Uint8List(8), Uint8List(1)),
          throwsArgumentError);
    });

    test('AES with signature and verification', () {
      final key = Crypto.generateRandomBytes(32);
      final nonce = Crypto.generateNonce();
      final (ciphertext, nonceB64, signature) =
          Crypto.encryptWithAESandGenerateSignature(
              key, nonce, utf8Bytes(samplePlaintext), serverPrivateKey);

      expect(Crypto.decryptWithAES(key, ciphertext, nonceB64),
          equals(samplePlaintext));
      final verifier = Crypto.fromBase64PublicKey(serverPublicKey);
      expect(verifier.verifySignature(ciphertext, signature), isTrue);

      final tampered = base64Decode(ciphertext);
      tampered[tampered.length - 1] ^= 1;
      expect(
          verifier.verifySignature(base64Encode(tampered), signature), isFalse);
    });
  });

  group('Signatures', () {
    test('sign/verify with raw and base64 APIs', () {
      final message = utf8Bytes('sign me');
      final sig = Crypto.signWithPrivateKey(serverPrivateKey, message);
      expect(sig.length, equals(256));
      expect(Crypto.verifyWithPublicKey(serverPublicKey, message, sig), isTrue);
      expect(
          Crypto.verifyWithPublicKey(
              serverPublicKey, utf8Bytes('sign me!'), sig),
          isFalse);

      final sigB64 = Crypto.sign(serverPrivateKey, message);
      expect(Crypto.verify(serverPublicKey, message, sigB64), isTrue);

      final (_, otherPub) = Crypto.generateRSAKeyPair();
      expect(Crypto.verify(otherPub, message, sigB64), isFalse);
      expect(Crypto.verify(serverPublicKey, message, 'AAAA'), isFalse);
    });
  });

  group('Envelope', () {
    test('encryptPayload / decryptResponse round trip', () async {
      final payload = {'Code': '172', 'Amount': 100.0, 'Currency': 'INR'};
      final envelope = await Crypto.encryptPayload(
          publicKey: serverPublicKey, payload: payload);
      expect(envelope.keys, containsAll(['payload', 'key', 'nonce']));
      expect(envelope.containsKey('signature'), isFalse);
      expect(base64Decode(envelope['key'] as String).length, equals(256));
      expect(base64Decode(envelope['nonce'] as String).length, equals(12));

      final decrypted = Crypto.decryptResponse(envelope, serverPrivateKey);
      expect(decrypted, equals(payload));
    });

    test('signed envelope verifies and rejects tampering', () {
      final (devicePriv, devicePub) = Crypto.generateRSAKeyPair();
      final (_, strangerPub) = Crypto.generateRSAKeyPair();
      final payload = utf8Bytes('signed payload');

      final envelope = Crypto.encryptEnvelope(
        recipientPublicKey: serverPublicKey,
        payload: payload,
        senderPrivateKey: devicePriv,
      );
      expect(envelope['signature'], isNotNull);

      expect(
          Crypto.decryptEnvelope(
            recipientPrivateKey: serverPrivateKey,
            envelope: envelope,
            senderPublicKey: devicePub,
          ),
          equals(payload));

      expect(
          () => Crypto.decryptEnvelope(
                recipientPrivateKey: serverPrivateKey,
                envelope: envelope,
                senderPublicKey: strangerPub,
              ),
          throwsStateError);

      final tampered = Map<String, dynamic>.from(envelope);
      final bytes = base64Decode(envelope['payload']!);
      bytes[0] ^= 1;
      tampered['payload'] = base64Encode(bytes);
      expect(
          () => Crypto.decryptEnvelope(
                recipientPrivateKey: serverPrivateKey,
                envelope: tampered,
                senderPublicKey: devicePub,
              ),
          throwsStateError);

      final unsigned = Map<String, dynamic>.from(envelope)..remove('signature');
      expect(
          () => Crypto.decryptEnvelope(
                recipientPrivateKey: serverPrivateKey,
                envelope: unsigned,
                senderPublicKey: devicePub,
              ),
          throwsArgumentError);
      // Without a sender key the signature is simply not checked.
      expect(
          Crypto.decryptEnvelope(
              recipientPrivateKey: serverPrivateKey, envelope: unsigned),
          equals(payload));
    });

    test('key-object variants interoperate with string variants', () {
      final (devicePriv, devicePub) = Crypto.generateRSAKeyPair();
      final server = Crypto.fromBase64PrivateKey(serverPrivateKey);
      final serverPub = Crypto.fromBase64PublicKey(serverPublicKey);
      final device = Crypto.fromBase64PrivateKey(devicePriv);
      final devicePubKey = Crypto.fromBase64PublicKey(devicePub);
      final payload = utf8Bytes('keys variant');

      for (final oaep in [false, true]) {
        final env = Crypto.encryptEnvelopeWithKeys(
            recipient: serverPub, payload: payload, signer: device, oaep: oaep);
        expect(
            Crypto.decryptEnvelope(
                recipientPrivateKey: serverPrivateKey,
                envelope: env,
                senderPublicKey: devicePub,
                oaep: oaep),
            equals(payload));

        final env2 = Crypto.encryptEnvelope(
            recipientPublicKey: serverPublicKey,
            payload: payload,
            senderPrivateKey: devicePriv,
            oaep: oaep);
        expect(
            Crypto.decryptEnvelopeWithKeys(
                recipient: server,
                envelope: env2,
                sender: devicePubKey,
                oaep: oaep),
            equals(payload));
        expect(
            () => Crypto.decryptEnvelopeWithKeys(
                recipient: server,
                envelope: env2,
                sender: serverPub,
                oaep: oaep),
            throwsStateError);
      }
      expect(() => serverPub.signBytes(payload), throwsArgumentError);
    });

    test('OAEP envelope round trip', () {
      final payload = utf8Bytes('oaep payload');
      final envelope = Crypto.encryptEnvelope(
          recipientPublicKey: serverPublicKey, payload: payload, oaep: true);
      expect(
          Crypto.decryptEnvelope(
              recipientPrivateKey: serverPrivateKey,
              envelope: envelope,
              oaep: true),
          equals(payload));
      expect(
          () => Crypto.decryptEnvelope(
              recipientPrivateKey: serverPrivateKey, envelope: envelope),
          throwsA(anything));
    });

    test('rejects envelopes with missing fields', () {
      expect(
          () => Crypto.decryptEnvelope(
              recipientPrivateKey: serverPrivateKey, envelope: {'key': 'x'}),
          throwsArgumentError);
    });

    test('accepts legacy base64-text AES key from older clients', () {
      final aesKey = Crypto.generateRandomBytes(32);
      final nonce = Crypto.generateNonce();
      final payload = utf8Bytes('{"legacy":true}');
      final (ciphertext, nonceB64) =
          Crypto.encryptWithAES(aesKey, nonce, payload);
      final legacyKey = Crypto.fromBase64PublicKey(serverPublicKey)
          .encryptWithPublicKey(base64Encode(aesKey));

      final decrypted = Crypto.decryptResponse({
        'payload': ciphertext,
        'nonce': nonceB64,
        'key': base64Encode(legacyKey),
      }, serverPrivateKey);
      expect(decrypted, equals({'legacy': true}));
    });

    test('decrypts real server response (uppercase fields, raw AES key)', () {
      final decrypted =
          Crypto.decryptResponse(legacyServerResponse, legacyServerPrivateKey);
      expect(decrypted['Code'], equals('118'));
      expect(decrypted['Name'], isA<String>());
      expect(decrypted['Duration'], equals(12));
    });
  });
}
